#include "../src/transport.hpp"
#include <cassert>
#include <iostream>
int main(int argc,char**){auto args=uw::transport::overrides(true);if(argc>1){for(auto&a:args)std::cout<<a<<'\n';return 0;}assert(uw::transport::overrides(false).empty());assert(args.size()==2);std::string good=R"({"result":{"config":{"model_provider":"usage_widget_https","model_providers":{"usage_widget_https":{"base_url":"https://chatgpt.com/backend-api/codex","wire_api":"responses","requires_openai_auth":true,"supports_websockets":false}}}}})";assert(uw::transport::verified(uw::Parser(good).parse()));for(auto pair:{std::pair<std::string,std::string>{"false","true"},{"https://chatgpt.com/backend-api/codex","https://api.openai.com/v1"},{"\"requires_openai_auth\":true","\"requires_openai_auth\":false"},{"\"model_provider\":\"usage_widget_https\"","\"model_provider\":\"openai\""}}){auto bad=good;auto pos=bad.find(pair.first);assert(pos!=std::string::npos);bad.replace(pos,pair.first.size(),pair.second);assert(!uw::transport::verified(uw::Parser(bad).parse()));}assert(!uw::transport::verified(uw::Parser(R"({"error":{"code":-32601}})").parse()));uw::transport::Verification check(true);check.begin(100000);assert(!check.ready()&&!check.tick(129999));assert(check.tick(130001)&&!check.ready()&&check.reason().find("timed out")!=std::string::npos);assert(check.observe(uw::Parser(good).parse())&&check.ready());assert(check.reason().find("verified")!=std::string::npos);check.begin(200000);assert(!check.ready()&&!check.tick(200001));assert(!check.observe(uw::Parser(R"({"error":{"code":-32601,"message":"sensitive server text"}})").parse()));assert(check.reason().find("-32601")!=std::string::npos&&check.reason().find("sensitive")==std::string::npos);assert(check.observe(uw::Parser(good).parse())&&check.ready());uw::transport::Verification normal(false);normal.begin(0);assert(!normal.observe(uw::Parser(R"({"result":{}})").parse()));assert(normal.observe(uw::Parser(R"({"result":{"config":{}}})").parse()));std::cout<<"PASS HTTPS process overrides, config validation rejection of wrong transport/provider/auth/endpoint, late-success recovery, deadline reset and redacted config error reasons\n";}
